/**
 * Speed-title ledger (PRD §6 Speed title rules, §17 Concurrency, Appendix A).
 * Replaying eligible attempts in verified completion order yields the same champion regardless of
 * upload order. A near tie leaves the incumbent in place; the margin is the larger of 5 s, 1% of
 * the benchmark, or the sum of both attempts' timing uncertainties. Titles never touch land.
 */

export interface TitleAttempt {
  id: string;
  userId: string;
  completedAt: number;
  elapsedMs: number;
  uncertaintyMs: number;
}

export type TitleEventKind = 'initial' | 'takeover' | 'improvement' | 'near_tie' | 'slower' | 'champion_no_improvement';

export interface TitleEvent {
  attemptId: string;
  userId: string;
  kind: TitleEventKind;
  benchmarkBeforeMs: number | null;
  requiredMs: number | null;
  marginMs: number | null;
  elapsedMs: number;
}

export interface TitleState {
  championId: string | null;
  benchmarkAttemptId: string | null;
  benchmarkMs: number | null;
  benchmarkUncertaintyMs: number;
  events: TitleEvent[];
}

export function requiredMarginMs(
  benchmarkMs: number,
  benchmarkUncertaintyMs: number,
  challengerUncertaintyMs: number,
  rules: typeof SPEED_RULES = SPEED_RULES
): number {
  return Math.max(
    Math.round(rules.marginMinSeconds.value * 1000),
    Math.ceil(benchmarkMs * rules.marginFraction.value),
    benchmarkUncertaintyMs + challengerUncertaintyMs
  );
}

export function orderAttempts(attempts: readonly TitleAttempt[]): TitleAttempt[] {
  return [...attempts].sort((a, b) => a.completedAt - b.completedAt || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

export function replayTitle(attempts: readonly TitleAttempt[], rules: typeof SPEED_RULES = SPEED_RULES): TitleState {
  const state: TitleState = { championId: null, benchmarkAttemptId: null, benchmarkMs: null, benchmarkUncertaintyMs: 0, events: [] };
  for (const att of orderAttempts(attempts)) {
    if (state.benchmarkMs === null) {
      state.championId = att.userId;
      state.benchmarkAttemptId = att.id;
      state.benchmarkMs = att.elapsedMs;
      state.benchmarkUncertaintyMs = att.uncertaintyMs;
      state.events.push({ attemptId: att.id, userId: att.userId, kind: 'initial', benchmarkBeforeMs: null, requiredMs: null, marginMs: null, elapsedMs: att.elapsedMs });
      continue;
    }
    const margin = requiredMarginMs(state.benchmarkMs, state.benchmarkUncertaintyMs, att.uncertaintyMs, rules);
    const required = state.benchmarkMs - margin;
    const beats = att.elapsedMs <= required;
    let kind: TitleEventKind;
    if (att.userId === state.championId) kind = beats ? 'improvement' : 'champion_no_improvement';
    else if (beats) kind = 'takeover';
    else kind = att.elapsedMs < state.benchmarkMs ? 'near_tie' : 'slower';
    state.events.push({ attemptId: att.id, userId: att.userId, kind, benchmarkBeforeMs: state.benchmarkMs, requiredMs: required, marginMs: margin, elapsedMs: att.elapsedMs });
    if (beats) {
      state.championId = att.userId;
      state.benchmarkAttemptId = att.id;
      state.benchmarkMs = att.elapsedMs;
      state.benchmarkUncertaintyMs = att.uncertaintyMs;
    }
  }
  return state;
}

/** Time a challenger needs to take the title, assuming a given challenger uncertainty. */
export function requiredTimeMs(benchmarkMs: number, benchmarkUncertaintyMs: number, challengerUncertaintyMs = 0): number {
  return benchmarkMs - requiredMarginMs(benchmarkMs, benchmarkUncertaintyMs, challengerUncertaintyMs);
}

export function formatDuration(ms: number): string {
  const totalTenths = Math.round(ms / 100);
  const tenths = totalTenths % 10;
  const totalSeconds = Math.floor(totalTenths / 10);
  const s = totalSeconds % 60;
  const m = Math.floor(totalSeconds / 60) % 60;
  const h = Math.floor(totalSeconds / 3600);
  const core = h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}` : `${m}:${String(s).padStart(2, '0')}`;
  return tenths ? `${core}.${tenths}` : core;
}
